// Topic menus: the page under the `demo` group (found by route_name, never by id) and
// one action row per permission, upserted by route_name / perms. Names are i18n keys: the page's in
// the module's web locale fragment (demo.topic.json), the actions' in menu.json (menu.action.*).
import { topicPerms } from '@qiwu/shared'
import type { EntityManager } from 'typeorm'
import { findRow, upsert } from '../../../db/seeds/upsert.js'

const ACTIONS: [perms: string, name: string][] = [
  [topicPerms.browse, 'menu.action.browse'],
  [topicPerms.view, 'menu.action.view'],
  [topicPerms.create, 'menu.action.create'],
  [topicPerms.modify, 'menu.action.modify'],
  [topicPerms.remove, 'menu.action.remove'],
]

export async function seedTopic(q: EntityManager): Promise<string[]> {
  // the group menu: one an administrator deleted skips these menus, a missing one is an error
  const parent = await findRow(q, 'iam_menu', { route_name: 'demo', kind: 'group' })
  if (!parent) throw new Error('seedTopic: the demo menu group is missing')
  if (parent.deleted) return ['seed: the demo menu group was deleted: the topic menus are skipped']
  const pageId = await upsert(
    q,
    'iam_menu',
    { route_name: 'demo-topic' },
    {
      kind: 'page',
      name: 'menu.demo.topic',
      route_path: '/demo/topics',
      component: 'demo/topic/index',
      component_name: 'DemoTopic',
      keep_alive: 1,
    },
    // written once: an administrator may move the page and change its icon and sort in the menu page
    { parent_id: parent.id, icon: 'lucide:list-tree', sort_no: 20 },
  )
  for (const [i, [perms, name]] of ACTIONS.entries())
    await upsert(
      q,
      'iam_menu',
      { kind: 'action', perms },
      { parent_id: pageId, name, sort_no: (i + 1) * 10 },
    )
  return []
}
